import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"2.1 接入只读信息源","description":"让用户看到系统读取了什么，以及来源是否可靠。","frontmatter":{"title":"2.1 接入只读信息源","description":"让用户看到系统读取了什么，以及来源是否可靠。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-2/2-1.md","filePath":"delivery/stage-2/2-1.md","lastUpdated":null}'),r={name:"delivery/stage-2/2-1.md"};function o(n,e,s,d,_,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_2-1-接入只读信息源" tabindex="-1">2.1 接入只读信息源 <a class="header-anchor" href="#_2-1-接入只读信息源" aria-label="Permalink to &quot;2.1 接入只读信息源&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 能安全地读取用户日常使用的信息来源，并把来源、时间和权限清楚地展示给用户。这个阶段只读，不发送、不修改、不删除。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先接一个邮件来源、一个日历来源、一个文件来源和一个知识库来源，不要一次铺开。</li><li>每次读取都记录来源、时间、账户和权限范围，用户能查到信息从哪里来。</li><li>对重复内容去重，对新增和变化做增量更新，避免每次全量重读。</li><li>遇到登录失效、权限不足或来源不可用时，明确告诉用户，不要静默失败。</li><li>提供断开来源和清除已读取内容的入口。</li><li>用真实账户验证：用户能看到系统读了什么，也能确认系统没有写入。</li></ol>',5)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
